const { item, itemId, getState, getActions, tgvContext } = options;
const win = aras.getMostTopWindowWithAras(window);
const dialog = win.ArasModules.Dialog.show('iframe', {
	title: aras.getResource(
		'../Modules/aras.innovator.TreeGridView',
		'filter-viewer_title'
	),
	aras,
	sourceTgvdNode: aras.itemsCache.getItem(itemId),
	changeableTgvdNode: item,
	dialogWidth: 512,
	dialogHeight: 448,
	content: '../Modules/aras.innovator.TreeGridView/Views/FilterViewer.html'
});

const { maxChildItems } = getState();
dialog.contentNode
	.querySelector('iframe')
	.contentWindow.addEventListener('load', (e) => {
		e.target.querySelector('input').value =
			maxChildItems < 0 ? '' : maxChildItems;
	});

return dialog.promise.then(function (maxChildItems) {
	if (!maxChildItems) {
		return;
	}
	getActions().updateMaxChildItems(maxChildItems);
	tgvContext.reload();
});
